create or replace function public.client_portal_list_v1362(p_section text,p_page integer default 1,p_page_size integer default 25,p_filters jsonb default '{}'::jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_uid uuid:=auth.uid();v_client bigint;v_role text;v_limit integer;v_offset integer;v_total bigint;v_rows jsonb;v_search text:=trim(coalesce(p_filters->>'search',''));begin if v_uid is null then raise exception 'AUTHENTICATION_REQUIRED' using errcode='42501';end if;select client_id,role into v_client,v_role from public.utilisateurs where auth_user_id=v_uid and statut='Actif' and role in('Client','Client-Admin');if v_client is null then raise exception 'CLIENT_SCOPE_MISSING' using errcode='42501';end if;v_limit:=least(100,greatest(1,coalesce(p_page_size,25)));v_offset:=(greatest(1,coalesce(p_page,1))-1)*v_limit;if p_section in('supports','infrastructures')then select count(*)into v_total from public.infrastructures i where i.client_id=v_client and(v_search=''or i.support_id ilike'%'||v_search||'%'or coalesce(i.site,'')ilike'%'||v_search||'%');select coalesce(jsonb_agg(to_jsonb(q)),'[]')into v_rows from(select i.support_id,i.site,i.type_site,i.type_support,i.emplacement_visibilite,i.client_id,'infrastructures.client_id' chemin_appartenance from public.infrastructures i where i.client_id=v_client and(v_search=''or i.support_id ilike'%'||v_search||'%'or coalesce(i.site,'')ilike'%'||v_search||'%')order by i.site nulls last,i.support_id limit v_limit offset v_offset)q;elsif p_section in('poster_directory','information_centers','information_centers_issues','stops','vehicles_trains')then return public.client_portal_list_v1361(p_section,p_page,p_page_size,p_filters);else return public.client_portal_list_v120(p_section,p_page,p_page_size,p_filters);end if;return jsonb_build_object('section',p_section,'page',greatest(1,coalesce(p_page,1)),'page_size',v_limit,'total',v_total,'rows',v_rows,'client_id',v_client,'role',v_role);end$$;
create or replace function public.client_ownership_summary_v1362(p_domain text default null)returns table(client_id bigint,client_name text,domain text,total bigint,assigned bigint,without_client bigint,ambiguous bigint,other_client bigint)language plpgsql stable security definer set search_path='' as $$begin if auth.uid()is null or not exists(select 1 from public.utilisateurs where auth_user_id=auth.uid()and statut='Actif'and role='Administrateur')then raise exception 'ADMIN_REQUIRED' using errcode='42501';end if;return query with d as(select i.client_id,'infrastructures'::text domain,count(*)::bigint total from public.infrastructures i group by i.client_id union all select c.client_id,'campaigns',count(*)from public.campagnes_maitres c group by c.client_id union all select p.client_id,'photos',count(*)from public.support_photos p group by p.client_id union all select e.client_id,'edt',count(*)from public.suivi_des_edt e group by e.client_id union all select p.client_id,'edt_phases',count(*)from public.edt_phases p group by p.client_id union all select e.client_id,'issues',count(*)from public.enjeux_terrain e group by e.client_id union all select r.client_id,'requests',count(*)from public.requetes_clients r group by r.client_id union all select v.client_id,'visuals',count(*)from public.campagne_visuels_formats v group by v.client_id union all select b.client_id,'work_orders',count(*)from public.bons_de_travail b group by b.client_id)select d.client_id,c.nom_client,d.domain,d.total,case when d.client_id is null then 0 else d.total end,case when d.client_id is null then d.total else 0 end,0::bigint,0::bigint from d left join public.clients c on c.id=d.client_id where p_domain is null or d.domain=p_domain;end$$;
create or replace function public.admin_preview_client_portal_context_v1362(p_target_user_id bigint)returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_admin uuid:=auth.uid();v_target public.utilisateurs%rowtype;v_base jsonb;v_total bigint;v_rows jsonb;begin if v_admin is null or not exists(select 1 from public.utilisateurs where auth_user_id=v_admin and statut='Actif'and role='Administrateur')then raise exception 'ADMIN_REQUIRED' using errcode='42501';end if;select*into v_target from public.utilisateurs where id=p_target_user_id and statut='Actif'and role in('Client','Client-Admin');if not found or v_target.client_id is null then raise exception 'TARGET_CLIENT_USER_NOT_FOUND';end if;v_base:=public.admin_preview_client_portal_context_v1361(p_target_user_id);select count(*)into v_total from public.infrastructures where client_id=v_target.client_id;select coalesce(jsonb_agg(to_jsonb(q)),'[]')into v_rows from(select support_id,site,type_site,type_support,emplacement_visibilite,client_id from public.infrastructures where client_id=v_target.client_id order by site nulls last,support_id limit 10)q;v_base:=jsonb_set(v_base,'{sections,supports}',jsonb_build_object('section','supports','page',1,'page_size',10,'total',v_total,'rows',v_rows),true);return v_base||jsonb_build_object('scope_version','v1362','diagnostic','OK','auth_uid_changed',false,'target_session_created',false);end$$;
create or replace function public.admin_transfer_data_client_v1362(p_domain text,p_entity_id text,p_new_client_id bigint,p_confirmation boolean)returns jsonb language plpgsql security definer set search_path='' as $$declare v_actor uuid:=auth.uid();v_old bigint;v_changed integer;begin if v_actor is null or not exists(select 1 from public.utilisateurs where auth_user_id=v_actor and statut='Actif'and role='Administrateur')then raise exception 'ADMIN_REQUIRED' using errcode='42501';end if;if not coalesce(p_confirmation,false)then raise exception 'TRANSFER_CONFIRMATION_REQUIRED';end if;if not exists(select 1 from public.clients where id=p_new_client_id and statut='Actif')then raise exception 'TARGET_CLIENT_NOT_FOUND';end if;if p_domain='infrastructures'then select client_id into v_old from public.infrastructures where support_id=p_entity_id for update;update public.infrastructures set client_id=p_new_client_id where support_id=p_entity_id;get diagnostics v_changed=row_count;elsif p_domain='campaigns'then select client_id into v_old from public.campagnes_maitres where id=p_entity_id::bigint for update;update public.campagnes_maitres set client_id=p_new_client_id where id=p_entity_id::bigint;get diagnostics v_changed=row_count;update public.campagnes_supports set client_id=p_new_client_id where campagne_id=p_entity_id::bigint;update public.campagne_visuels_formats set client_id=p_new_client_id where campagne_id=p_entity_id::bigint;update public.support_photos set client_id=p_new_client_id where campagne_id=p_entity_id::bigint;update public.suivi_des_edt set client_id=p_new_client_id where campagne_id=p_entity_id::bigint;delete from public.client_campaign_access where campaign_id=p_entity_id::bigint;else raise exception 'UNSUPPORTED_TRANSFER_DOMAIN';end if;if v_changed<>1 then raise exception 'TRANSFER_ENTITY_NOT_FOUND';end if;insert into public.activity_events(occurred_at,actor_id,action,module,entity_type,entity_id,old_value,new_value,client_id,source,source_system,source_record_id,status)values(now(),v_actor,'DATA_TRANSFERRED_CLIENT','client_ownership',p_domain,p_entity_id,jsonb_build_object('client_id',v_old),jsonb_build_object('client_id',p_new_client_id),p_new_client_id::text,'admin','admin',p_entity_id,'success');return jsonb_build_object('ok',true,'domain',p_domain,'entity_id',p_entity_id,'old_client_id',v_old,'new_client_id',p_new_client_id);end$$;
