e_record_id,source_occurred_at,reconstruction_method,confidence,status)values(now(),v_actor,'DATA_TRANSFERRED_CLIENT','client_ownership',p_domain,p_entity_id,jsonb_build_object('client_id',v_old),jsonb_build_object('client_id',p_new_client_id),p_new_client_id::text,'admin','admin',p_entity_id,now(),'direct','high','success');return jsonb_build_object('ok',true,'domain',p_domain,'entity_id',p_entity_id,'old_client_id',v_old,'new_client_id',p_new_client_id);end$$;
